import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 결재 진행 상태 허용 값 (결정)
const STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];
// 가정: 문서번호 형식은 APR-YYYYMMDD-일련번호(4자리), 일 단위 채번
const DOC_NUMBER_PREFIX = 'APR-';
// 가정: 채번 동시성 제어용 advisory lock 키
const NUMBER_LOCK_KEY = 4701;
// 가정: 상신된 문서의 첨부 소유 대상 유형 값
const OWNER_TYPE_APPROVAL = '결재문서';
// 가정: 첨부 중복 기준은 같은 내용 해시 + 같은 소유 대상(유형·식별자)

function fail(message: string): never {
  throw new ApiError(400, 'VALIDATION_FAILED', message);
}

function intOf(value: unknown, label: string): number {
  const n = typeof value === 'string' && value.trim() !== '' ? Number(value) : value;
  if (typeof n !== 'number' || !Number.isInteger(n) || n <= 0) {
    fail(label + ' 값이 올바르지 않습니다.');
  }
  return n as number;
}

function textOf(value: unknown, label: string, max: number, required: boolean): string | null {
  if (value === undefined || value === null || value === '') {
    if (required) {
      fail(label + ' 값을 입력하세요.');
    }
    return null;
  }
  if (typeof value !== 'string' || value.trim() === '') {
    fail(label + ' 값이 올바르지 않습니다.');
  }
  if ((value as string).length > max) {
    fail(label + ' 값은 ' + max + '자 이하여야 합니다.');
  }
  return value as string;
}

function boolOf(value: unknown, label: string): boolean {
  if (value === undefined || value === null) {
    return false;
  }
  if (typeof value !== 'boolean') {
    fail(label + ' 값이 올바르지 않습니다.');
  }
  return value as boolean;
}

@Controller('api/v1')
export class FnSfr00307Controller {
  @Post('/approval-documents')
  @HttpCode(200)
  async createApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '시스템 관리자');
    const data = checks.inputOf(req.body);
    const formId = intOf(data['approvalFormId'], '결재양식');
    const title = textOf(data['title'], '문서 제목', 500, true);
    const body = textOf(data['body'], '문서 본문', 10000000, false);
    const businessType = textOf(data['linkedBusinessType'], '연계 업무 유형', 50, true);
    const businessId = intOf(data['linkedBusinessId'], '연계 업무 식별자');
    const isUrgent = boolOf(data['isUrgent'], '긴급결재 여부');
    const isSecret = boolOf(data['isSecret'], '보안문서 여부');
    const rawIds = data['attachmentIds'];
    let attachmentIds: number[] = [];
    if (rawIds !== undefined && rawIds !== null) {
      if (!Array.isArray(rawIds)) {
        fail('첨부파일 ID 목록이 올바르지 않습니다.');
      }
      attachmentIds = (rawIds as unknown[]).map((v) => intOf(v, '첨부파일 ID'));
    }
    return transaction(async (db) => {
      const forms = await db.query(
        `SELECT approval_form_id FROM approval_form
         WHERE approval_form_id = CAST(:formId AS bigint) AND use_status = :useStatus`,
        { formId, useStatus: '사용' },
      );
      if (forms.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '결재양식을 찾을 수 없습니다.');
      }
      const employees = await db.query(
        `SELECT department_id AS "departmentId" FROM employee
         WHERE employee_id = CAST(:userId AS bigint)`,
        { userId: user.id },
      );
      if (employees.length === 0 || employees[0]['departmentId'] === null) {
        fail('기안자의 소속 부서가 없어 상신할 수 없습니다.');
      }
      const departmentId = employees[0]['departmentId'];
      // 이미 결재가 진행 중이거나 승인된 업무 문서는 수정·재상신할 수 없다
      const duplicated = await db.query(
        `SELECT approval_document_id FROM approval_document
         WHERE linked_business_type = :businessType
           AND linked_business_id = CAST(:businessId AS bigint)
           AND approval_status IN ('결재대기', '진행중', '보류', '승인')`,
        { businessType, businessId },
      );
      if (duplicated.length > 0) {
        throw new ApiError(
          409,
          'BUSINESS_DOCUMENT_NOT_SUBMITTABLE',
          '이미 상신되어 결재가 진행 중인 업무 문서입니다.',
        );
      }
      for (const attachmentId of attachmentIds) {
        const found = await db.query(
          `SELECT attachment_id FROM attachment WHERE attachment_id = CAST(:attachmentId AS bigint)`,
          { attachmentId },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', '첨부파일을 찾을 수 없습니다.');
        }
      }
      await db.query('SELECT pg_advisory_xact_lock(CAST(:key AS bigint))', { key: NUMBER_LOCK_KEY });
      const numbers = await db.query(
        `SELECT CAST(:prefix AS text) || to_char(now(), 'YYYYMMDD') || '-'
                || lpad(CAST(COUNT(*) + 1 AS text), 4, '0') AS "documentNumber"
         FROM approval_document
         WHERE document_number LIKE CAST(:prefix AS text) || to_char(now(), 'YYYYMMDD') || '-%'`,
        { prefix: DOC_NUMBER_PREFIX },
      );
      const rows = await db.query(
        `INSERT INTO approval_document (
           approval_form_id, drafter_id, drafter_department_id, document_number, title, body,
           approval_status, is_urgent, is_secret, linked_business_type, linked_business_id,
           submitted_at, created_at, updated_at
         ) VALUES (
           CAST(:formId AS bigint), CAST(:userId AS bigint), CAST(:departmentId AS bigint),
           :documentNumber, :title, :body,
           :status, :isUrgent, :isSecret, :businessType, CAST(:businessId AS bigint),
           now(), now(), now()
         )
         RETURNING approval_document_id AS "approvalDocumentId",
                   document_number AS "documentNumber",
                   approval_status AS "approvalStatus"`,
        {
          formId,
          userId: user.id,
          departmentId,
          documentNumber: numbers[0]['documentNumber'],
          title,
          body,
          status: '결재대기',
          isUrgent,
          isSecret,
          businessType,
          businessId,
        },
      );
      for (const attachmentId of attachmentIds) {
        await db.execute(
          `UPDATE attachment
           SET owner_type = :ownerType, owner_id = CAST(:ownerId AS bigint), updated_at = now()
           WHERE attachment_id = CAST(:attachmentId AS bigint)`,
          { ownerType: OWNER_TYPE_APPROVAL, ownerId: rows[0]['approvalDocumentId'], attachmentId },
        );
      }
      return rows[0];
    });
  }

  @Post('/approval-documents/result')
  @HttpCode(200)
  async receiveApprovalResult(@Req() req: Request) {
    currentUser(req);
    const data = checks.inputOf(req.body);
    const documentId = intOf(data['approvalDocumentId'], '결재문서 ID');
    const status = textOf(data['approvalStatus'], '결재 진행 상태', 10, true) as string;
    if (!STATUSES.includes(status)) {
      throw new ApiError(422, 'INVALID_APPROVAL_STATUS', '허용되지 않는 결재 상태 값입니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT approval_document_id FROM approval_document
         WHERE approval_document_id = CAST(:documentId AS bigint)`,
        { documentId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '결재문서를 찾을 수 없습니다.');
      }
      await db.execute(
        `UPDATE approval_document
         SET approval_status = :status,
             completed_at = CASE WHEN CAST(:status AS text) = '완료' THEN now() ELSE completed_at END,
             updated_at = now()
         WHERE approval_document_id = CAST(:documentId AS bigint)`,
        { status, documentId },
      );
      const rows = await db.query(
        `SELECT approval_status AS "approvalStatus" FROM approval_document
         WHERE approval_document_id = CAST(:documentId AS bigint)`,
        { documentId },
      );
      return rows[0];
    });
  }

  @Post('/attachments')
  @HttpCode(200)
  async createAttachment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '시스템 관리자');
    const data = checks.inputOf(req.body);
    // 가정: file 문자열을 업로드 파일명이자 내용으로 취급한다
    const file = textOf(data['file'], '업로드 파일', 255, true) as string;
    const ownerType = textOf(data['ownerType'], '소유 대상 유형', 50, false);
    const ownerId =
      data['ownerId'] === undefined || data['ownerId'] === null || data['ownerId'] === ''
        ? null
        : intOf(data['ownerId'], '소유 대상 식별자');
    return transaction(async (db) => {
      const hashes = await db.query(
        `SELECT encode(sha256(convert_to(CAST(:file AS text), 'UTF8')), 'hex') AS hash`,
        { file },
      );
      const hash = hashes[0]['hash'];
      const duplicated = await db.query(
        `SELECT attachment_id FROM attachment
         WHERE content_hash = :hash
           AND owner_type IS NOT DISTINCT FROM CAST(:ownerType AS varchar)
           AND owner_id IS NOT DISTINCT FROM CAST(:ownerId AS bigint)`,
        { hash, ownerType, ownerId },
      );
      if (duplicated.length > 0) {
        throw new ApiError(409, 'DUPLICATE_ATTACHMENT', '동일한 파일이 이미 등록되어 있습니다.');
      }
      const rows = await db.query(
        `INSERT INTO attachment (
           uploader_id, owner_type, owner_id, file_name, file_ext, file_size,
           content_hash, created_at, updated_at
         ) VALUES (
           CAST(:userId AS bigint), CAST(:ownerType AS varchar), CAST(:ownerId AS bigint), :file,
           substring(CAST(:file AS text) from '\\.([^.]+)$'),
           octet_length(CAST(:file AS text)),
           :hash, now(), now()
         )
         RETURNING attachment_id AS "attachmentId", file_name AS "fileName"`,
        { userId: user.id, ownerType, ownerId, file, hash },
      );
      return rows[0];
    });
  }
}

