import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  NumberInput,
  RefName,
  Select,
  Tiles,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

const STATUS_OPTIONS: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['진행중', '진행중'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['완료', '완료'],
];

const YES_NO: [string, string][] = [
  ['false', '아니오'],
  ['true', '예'],
];

// 결과를 반영할 수 있는 현재 상태 (종료 상태인 완료·반려·회수는 처리 버튼을 숨긴다)
const OPEN_STATUSES = ['결재대기', '진행중', '보류', '승인'];

export default function FnSfr00307Page({ role, notify }: PageProps) {
  const [docs, setDocs] = useState<Row[]>([]);
  const [attachments, setAttachments] = useState<Row[]>([]);
  const [drawer, setDrawer] = useState<'create' | 'attach' | 'result' | null>(null);
  const [target, setTarget] = useState<Row | null>(null);

  const [formId, setFormId] = useState<number | string>('');
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [businessType, setBusinessType] = useState('');
  const [businessId, setBusinessId] = useState<number | string>('');
  const [isUrgent, setIsUrgent] = useState('false');
  const [isSecret, setIsSecret] = useState('false');
  const [pickedIds, setPickedIds] = useState<number[]>([]);

  const [file, setFile] = useState('');
  const [ownerType, setOwnerType] = useState('');
  const [ownerId, setOwnerId] = useState<number | string>('');

  const [newStatus, setNewStatus] = useState('');

  function openCreate() {
    setFormId('');
    setTitle('');
    setBody('');
    setBusinessType('');
    setBusinessId('');
    setIsUrgent('false');
    setIsSecret('false');
    setPickedIds([]);
    setDrawer('create');
  }

  function openAttach() {
    setFile('');
    setOwnerType('');
    setOwnerId('');
    setDrawer('attach');
  }

  function openResult(row: Row) {
    setTarget(row);
    setNewStatus('');
    setDrawer('result');
  }

  function close() {
    setDrawer(null);
    setTarget(null);
  }

  async function submitCreate() {
    if (formId === '') {
      throw new Error('결재양식을 선택하세요.');
    }
    if (title.trim() === '') {
      throw new Error('문서 제목을 입력하세요.');
    }
    if (businessType.trim() === '') {
      throw new Error('연계 업무 유형을 입력하세요.');
    }
    if (businessId === '') {
      throw new Error('연계 업무 식별자를 입력하세요.');
    }
    const res = await call('POST', '/approval-documents', role, {
      approvalFormId: formId,
      title,
      body: body === '' ? undefined : body,
      linkedBusinessType: businessType,
      linkedBusinessId: businessId,
      isUrgent: isUrgent === 'true',
      isSecret: isSecret === 'true',
      attachmentIds: pickedIds,
    });
    setDocs((prev) => [
      {
        ...res,
        title,
        approvalFormId: formId,
        linkedBusinessType: businessType,
        linkedBusinessId: businessId,
      },
      ...prev,
    ]);
    notify('전자결재로 상신했습니다.');
    close();
  }

  async function submitResult() {
    if (newStatus === '') {
      throw new Error('결재 진행 상태를 선택하세요.');
    }
    const res = await call('POST', '/approval-documents/result', role, {
      approvalDocumentId: target?.['approvalDocumentId'],
      approvalStatus: newStatus,
    });
    setDocs((prev) =>
      prev.map((d) =>
        d['approvalDocumentId'] === target?.['approvalDocumentId']
          ? { ...d, approvalStatus: res['approvalStatus'] }
          : d,
      ),
    );
    notify('결재 결과를 반영했습니다.');
    close();
  }

  async function submitAttach() {
    if (file.trim() === '') {
      throw new Error('업로드 파일을 입력하세요.');
    }
    const res = await call('POST', '/attachments', role, {
      file,
      ownerType: ownerType === '' ? undefined : ownerType,
      ownerId: ownerId === '' ? undefined : ownerId,
    });
    setAttachments((prev) => [res, ...prev]);
    notify('첨부파일을 등록했습니다.');
    close();
  }

  function addAttachment(value: string) {
    const id = Number(value);
    if (value !== '' && !pickedIds.includes(id)) {
      setPickedIds([...pickedIds, id]);
    }
  }

  function nameOfAttachment(id: number): string {
    const found = attachments.find((a) => a['attachmentId'] === id);
    return found ? String(found['fileName']) : String(id);
  }

  const progressCount = docs.filter((d) => OPEN_STATUSES.includes(String(d['approvalStatus']))).length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>상신 현황</h2>
        <Tiles
          items={[
            ['상신 문서', docs.length],
            ['결재 진행', progressCount],
            ['등록 첨부', attachments.length],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>상신 문서</h2>
        <Band total={docs.length}>
          <button onClick={openCreate}>전자결재 상신</button>
        </Band>
        <DataTable
          rows={docs}
          empty="이 화면에서 상신한 문서가 없습니다."
          columns={[
            { key: 'documentNumber', label: '문서번호' },
            { key: 'title', label: '문서 제목' },
            {
              key: 'approvalFormId',
              label: '결재양식',
              render: (row) => <RefName table="approval_form" role={role} value={row['approvalFormId']} />,
            },
            {
              key: 'approvalStatus',
              label: '결재 진행 상태',
              render: (row) => <Badge value={row['approvalStatus']} />,
            },
            {
              key: 'action',
              label: '처리',
              render: (row) =>
                OPEN_STATUSES.includes(String(row['approvalStatus'])) ? (
                  <button onClick={() => openResult(row)}>결과 반영</button>
                ) : (
                  <span />
                ),
            },
          ]}
        />
      </section>
      <section className="box span-4">
        <h2>상신 첨부</h2>
        <Band total={attachments.length}>
          <button onClick={openAttach}>첨부 등록</button>
        </Band>
        <DataTable
          rows={attachments}
          empty="등록한 첨부파일이 없습니다."
          columns={[{ key: 'fileName', label: '파일명' }]}
        />
      </section>
      {drawer === 'create' && (
        <Drawer title="전자결재 상신" onClose={close}>
          <Form onSubmit={submitCreate} submit="상신">
            <Field label="결재양식" required>
              <LookupSelect table="approval_form" role={role} value={formId} onChange={setFormId} />
            </Field>
            <Field label="문서 제목" required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="문서 본문" wide>
              <TextInput value={body} onChange={setBody} multiline />
            </Field>
            <Field label="연계 업무 유형" required>
              <TextInput value={businessType} onChange={setBusinessType} />
            </Field>
            <Field label="연계 업무 식별자" required>
              <NumberInput value={businessId} onChange={setBusinessId} />
            </Field>
            <Field label="긴급결재 여부">
              <Select value={isUrgent} onChange={setIsUrgent} options={YES_NO} placeholder="선택" />
            </Field>
            <Field label="보안문서 여부">
              <Select value={isSecret} onChange={setIsSecret} options={YES_NO} placeholder="선택" />
            </Field>
            <Field label="첨부파일" wide hint={pickedIds.map(nameOfAttachment).join(', ')}>
              <Select
                value=""
                onChange={addAttachment}
                options={attachments.map((a): [string, string] => [
                  String(a['attachmentId']),
                  String(a['fileName']),
                ])}
                placeholder="첨부파일 추가"
              />
            </Field>
          </Form>
        </Drawer>
      )}
      {drawer === 'result' && target && (
        <Drawer title="결재 결과 반영" onClose={close}>
          <Form onSubmit={submitResult} submit="반영">
            <Field label="결재문서 ID" wide>
              <span>{String(target['documentNumber'] ?? '')}</span>
            </Field>
            <Field label="결재 진행 상태" required>
              <Select value={newStatus} onChange={setNewStatus} options={STATUS_OPTIONS} />
            </Field>
          </Form>
        </Drawer>
      )}
      {drawer === 'attach' && (
        <Drawer title="첨부 등록" onClose={close}>
          <Form onSubmit={submitAttach} submit="등록">
            <Field label="업로드 파일" required wide>
              <TextInput value={file} onChange={setFile} />
            </Field>
            <Field label="소유 대상 유형">
              <TextInput value={ownerType} onChange={setOwnerType} />
            </Field>
            <Field label="소유 대상 식별자">
              <NumberInput value={ownerId} onChange={setOwnerId} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
